import type { Metadata } from 'next'
import type { CSSProperties } from 'react'
import Link from 'next/link'
import Footer from '@/components/Footer'
import OrganicCtaLink from '@/components/OrganicCtaLink'
import TopicGeneratorForm from '@/app/youtube-shorts-from-topic/TopicGeneratorForm'
import { PUBLIC_EXAMPLES } from '@/lib/publicExamples'
import { PaginaClaraCards, PaginaClaraTopo, PaginaClaraVitrine } from '@/components/seo/PaginaClara' // KINEO-PAGINAS-IA-CLARAS-2110 — o menu do topo, os 4 cards e a vitrine atual da home (no lugar do exemplo e dos 3 vídeos velhos)
import { PAGINA_CLARA_CLASSE, PAGINA_CLARA_FUNDO } from '@/lib/seo/paginasIaClaras2110' // KINEO-PAGINAS-IA-CLARAS-2110
import ExitIntentOffer from '@/components/ExitIntentOffer'
import { buildBlankStudioSignupHref } from '@/lib/growth/publicCreationIntent'
import { getFreeTierOffer, swapFreeTierCopy as ft, FREE_FILM_LABEL } from '@/lib/freeTierOffer'
import AffiliateLandingContext from '@/components/AffiliateLandingContext'
import {
  affiliateLandingContext,
  type PublicSearchParams,
} from '@/lib/growth/affiliateLandingContext'
import { freeShortsAlternates } from '@/lib/seo/freeShortsGeneratorLangs'
// KINEO-PONTE-ACIMA-DA-DOBRA-2026-09-23 — ponte roteiro → Seedance acima da dobra (fundador 23/09, jogada 3).
import PaidSeedanceBridge from '@/components/PaidSeedanceBridge'
import BuyCreatorCta from '@/components/BuyCreatorCta' // KINEO-PAGINAS-QUE-VENDEM-2026-10-12
import { ENGINES } from '@/lib/growth/enginePageCatalog'
import { enginePaused } from '@/lib/engineLaunch'
import { headers } from 'next/headers' // KINEO-POUSO-AFILIADO-CELULAR-1311
import { filmeGratisPermitido, paisDoRequest } from '@/lib/freeFilmPolicy' // KINEO-POUSO-AFILIADO-CELULAR-1311
import { TRIAL_FREE_FILM_SECONDS } from '@/lib/freeTierOffer' // KINEO-POUSO-AFILIADO-CELULAR-1311
import { REGIAO_PAGA_BANNER_COPY } from '@/lib/growth/regiaoPaga1011' // KINEO-POUSO-AFILIADO-CELULAR-1311 (revisão da CEO)

// [KINEO-TRIAL-SWAP-2026-08-07] — oferta do free tier (flag OFF = copy atual).
const OFFER = getFreeTierOffer()

const BASE = 'https://www.usekineo.com'
const CAMPAIGN = 'push60_free_ai_shorts_generator'
const FORM_ID = 'free-ai-shorts-generator-form'
const FEATURED_EXAMPLE = PUBLIC_EXAMPLES[1]
const PUBLICATION_DATE = '2026-07-23T00:00:00.000Z'
// KINEO-PREVIA-AFILIADO-1311 [CEO 13/11] — a prévia do bloco do parceiro troca o corte de agosto (example-sentinel, imagem de banco) por um
// filme narrado que JÁ está na home e é o que o filme de hoje entrega (filme-mary-celeste da galeria, Kling 4.0, 09/11), em versão leve:
// 360×640, sem áudio, 6,5 s, 234 KB (public/previews/afiliado/mary-celeste-360.mp4; pôster webp de 16 KB).
const PARTNER_PREVIEW = { poster: '/posters/afiliado/mary-celeste-360.webp', video: '/previews/afiliado/mary-celeste-360.mp4', alt: 'The ghost ship Mary Celeste, a narrated Short made with Kineo' }

const FEATURES = [
  {
    t: 'From idea to full Short',
    d: 'Kineo creates the script, AI voiceover, vertical visuals, pacing, and captions from one topic.',
  },
  {
    t: 'No card for the first test',
    d: ft(OFFER, 'New accounts can create up to 3 watermarked Fast videos every 24 hours before choosing a paid plan.', OFFER.copy.sentence),
  },
  {
    t: 'Built for faceless channels',
    d: 'Use it for mystery, money, AI, geography, facts, history, psychology, and other repeatable Shorts formats.',
  },
] as const

const FAQ = [
  {
    q: 'Is there a free AI Shorts generator?',
    a: `Yes. ${ft(OFFER, 'Kineo lets new accounts create up to 3 watermarked Fast videos every 24 hours with no credit card.', OFFER.copy.sentence)} Paid plans unlock clean exports and higher quality engines.`,
  },
  {
    q: 'Does it generate the whole Short or only a script?',
    a: 'It generates the whole Short: hook-first script, AI voiceover, vertical visuals, captions, and an MP4 export.',
  },
  {
    q: 'Can I use it without showing my face?',
    a: 'Yes. Kineo is built for faceless Shorts, so you do not need to film yourself, record your voice, or edit a timeline.',
  },
  {
    q: 'What happens after your free film?', // KINEO-PAGINAS-QUE-VENDEM-2026-10-12 — o grátis é UM filme, não "videos"
    a: `${OFFER.copy.sentence} For recurring production, compare the monthly plans and the credits required by your chosen engine and duration. You can choose a plan before making your first film.`,
  },
] as const

export const metadata: Metadata = {
  title: 'Free AI Shorts Generator - Create Faceless Shorts With No Card | Kineo',
  description:
    `Create faceless Shorts with script, AI voiceover, visuals and captions. Trial: ${OFFER.copy.planLimitLine}. Compare films and plans before you choose.`,
  alternates: {
    canonical: `${BASE}/free-ai-shorts-generator`,
    // KINEO-PORTAS-16-LINGUAS-2026-09-20 — hreflang das 16 portas (en/pt/es + 13 em /free-shorts-generator/<lang>).
    languages: freeShortsAlternates(BASE),
  },
  openGraph: {
    title: 'Free AI Shorts Generator - Kineo',
    description:
      'Type one idea and create a faceless Short with script, AI voiceover, visuals, captions, and MP4 export.',
    url: `${BASE}/free-ai-shorts-generator`,
    siteName: 'Kineo (usekineo.com)', // KINEO-MARCA-2026-10-06
    type: 'website',
    images: [{ url: FEATURED_EXAMPLE.posterPath, width: 360, height: 640 }],
    videos: [{ url: FEATURED_EXAMPLE.videoPath, width: 360, height: 640, type: 'video/mp4' }],
  },
  twitter: {
    card: 'summary_large_image',
    title: 'Free AI Shorts Generator | Kineo',
    description: `Create a faceless AI Short from one idea. Trial: ${OFFER.copy.planLimitLine}.`,
    images: [FEATURED_EXAMPLE.posterPath],
  },
}

export default function FreeAiShortsGeneratorPage({ searchParams }: { searchParams?: PublicSearchParams }) {
  const signupUrl = buildBlankStudioSignupHref({ campaign: CAMPAIGN })
  const partnerContext = affiliateLandingContext(searchParams, 'video')
  // KINEO-POUSO-AFILIADO-CELULAR-1311 [dono 13/11, "sim"] — SÓ para quem chega pelo link do parceiro (a mesma condição
  // que já mostrava o bloco): prévia muda no bloco, a linha do grátis certa para o país e o formulário logo abaixo dele,
  // na 1ª tela do celular. Quem não vem de afiliado vê a página igual, na mesma ordem. Nenhum texto da página saiu: o
  // formulário só muda de lugar para o afiliado. País sem filme grátis (Índia, Paquistão…) não recebe promessa de filme.
  const partnerCountry = partnerContext ? paisDoRequest(headers()) : null
  const partnerFreeFilm = partnerContext ? filmeGratisPermitido(partnerCountry) : false
  const partnerOfferLine = partnerContext && partnerFreeFilm ? `Your first ${TRIAL_FREE_FILM_SECONDS}-second film is free, watermarked, no card.` : null
  // Revisão da CEO 13/11 — país SEM filme grátis: o bloco inteiro diz o que a pessoa recebe de verdade (roteiro + cenas em
  // imagens, /studio/previa), com as palavras já aprovadas do aviso de região (REGIAO_PAGA_BANNER_COPY). O texto padrão do
  // bloco ("free first test… judge the scripted, voiced, captioned video yourself", "Try the free video workflow") promete
  // um vídeo que esse país não recebe, e "first scene" não é o que a prévia entrega (são 3–4 imagens e o roteiro).
  const partnerContextShown = partnerContext && !partnerFreeFilm
    ? { ...partnerContext, heading: REGIAO_PAGA_BANNER_COPY.en.title, body: REGIAO_PAGA_BANNER_COPY.en.body, action: 'Start with my idea' }
    : partnerContext
  const formCopy = {
    label: 'What should your free AI Short be about?',
    placeholder: 'Type one topic or paste your script',
    submit: 'Create my free Short',
    examplesLabel: 'Free Short ideas',
    note: ft(
      OFFER,
      'Your idea is carried into signup so the first Fast video can start without a card.',
      // KINEO-PAGINAS-QUE-VENDEM-2026-10-12 — a frase antiga do recuo para o motor rápido prometia o Kineo 1, fora da entrada desde 29/09.
      `Your idea stays attached through signup and becomes your ${FREE_FILM_LABEL}, watermarked, no card.`,
    ),
  }
  const partnerNoFilmCopy = {
    ...formCopy,
    label: 'What should your AI Short be about?',
    submit: 'Start with my idea',
    examplesLabel: 'Short ideas',
    note: 'Your idea stays attached through signup. Kineo writes the script and shows your scenes as images — free.',
  }
  const topicForm = (
    <TopicGeneratorForm
      campaign={CAMPAIGN}
      source={CAMPAIGN}
      formId={FORM_ID}
      creationIntent={OFFER.reverseTrial ? 'trial_best' : 'fast'}
      marginTop={partnerContext ? 0 : undefined}
      examples={[
        'The island nobody is allowed to visit',
        'The money habit that quietly makes people broke',
        'Why AI agents are replacing old software',
      ]}
      copy={partnerContext && !partnerFreeFilm ? partnerNoFilmCopy : formCopy}
    />
  )
  const h2: CSSProperties = { fontSize: 'clamp(1.3rem, 3.5vw, 1.75rem)', fontWeight: 650, margin: '44px 0 12px' }
  const p: CSSProperties = { color: '#5A5F67', fontSize: '1rem', lineHeight: 1.65, margin: '0 0 12px' }
  const card: CSSProperties = { background: '#FFFFFF', border: '1px solid #E4E4E0', borderRadius: 14, padding: '16px 18px' }
  const faqJsonLd = {
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: FAQ.map((item) => ({
      '@type': 'Question',
      name: item.q,
      acceptedAnswer: { '@type': 'Answer', text: item.a },
    })),
  }
  const videoJsonLd = {
    '@context': 'https://schema.org',
    '@type': 'VideoObject',
    name: FEATURED_EXAMPLE.title,
    description: FEATURED_EXAMPLE.description,
    thumbnailUrl: [`${BASE}${FEATURED_EXAMPLE.posterPath}`],
    uploadDate: PUBLICATION_DATE,
    duration: `PT${FEATURED_EXAMPLE.previewDurationSeconds}S`,
    contentUrl: `${BASE}${FEATURED_EXAMPLE.videoPath}`,
    embedUrl: `${BASE}/free-ai-shorts-generator#example`,
  }

  return (
    <main className={PAGINA_CLARA_CLASSE} style={{ minHeight: '100vh', background: PAGINA_CLARA_FUNDO, color: '#0E1116', fontFamily: 'var(--font-sans), Arial, sans-serif' }}>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(faqJsonLd).replace(/</g, '\\u003c') }} />
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(videoJsonLd).replace(/</g, '\\u003c') }} />
      <PaginaClaraTopo />{/* KINEO-PAGINAS-IA-CLARAS-2110 */}
      <div style={{ maxWidth: 880, margin: '0 auto', padding: '64px 20px 88px' }}>
        <AffiliateLandingContext
          context={partnerContextShown}
          targetId={FORM_ID}
          country={partnerCountry}
          offerLine={partnerOfferLine}
          preview={partnerContext ? PARTNER_PREVIEW : null}
        />
        {partnerContext && <div style={{ margin: '0 0 30px' }}>{topicForm}</div>}
        <span style={{ display: 'inline-block', fontSize: 12, fontWeight: 750, letterSpacing: '0.12em', textTransform: 'uppercase', color: '#0A5CFF', border: '1px solid rgba(10,92,255,0.35)', background: '#E8EFFF', borderRadius: 999, padding: '6px 12px' }}>
          Free AI Shorts Generator
        </span>
        <h1 style={{ fontSize: 'clamp(1.9rem, 5vw, 2.9rem)', fontWeight: 650, lineHeight: 1.1, margin: '18px 0 0' }}>
          Create a Faceless AI Short for Free
        </h1>
        <p style={{ fontSize: '1.08rem', color: '#5A5F67', lineHeight: 1.6, margin: '16px 0 0' }}>
          Type one idea and Kineo generates a ready-to-post vertical Short: script, AI voiceover, visuals, captions, and MP4 export. {ft(OFFER, 'Try the Fast workflow with no credit card.', 'Your active trial starts with the best engine it can cover — Seedance when eligible.')}
        </p>
        <PaginaClaraCards />{/* KINEO-PAGINAS-IA-CLARAS-2110 — os 4 cards da home logo abaixo do título e da 1ª frase (a resposta citável continua sendo o 1º parágrafo depois do H1) */}
        {/* KINEO-PAGINAS-QUE-VENDEM-2026-10-12 — compra direta do Creator na primeira dobra; o botão grátis vira o secundário. */}
        {!enginePaused(ENGINES.seedance.param) && (
          <BuyCreatorCta
            page="free_ai_shorts_generator"
            align="left"
            secondary={
              <OrganicCtaLink href={`#${FORM_ID}`} source={CAMPAIGN} placement="hero" style={{ border: '1px solid #D2D2CD', color: '#0E1116', fontWeight: 800, padding: '14px 22px', borderRadius: 980, textDecoration: 'none' }}>
                Generate a free Short
              </OrganicCtaLink>
            }
          />
        )}
        {!enginePaused(ENGINES.seedance.param) && <PaidSeedanceBridge from="free_ai_shorts_generator" compact />}
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, margin: '26px 0 0' }}>
          {enginePaused(ENGINES.seedance.param) && (
            <OrganicCtaLink href={`#${FORM_ID}`} source={CAMPAIGN} placement="hero" style={{ background: '#0A5CFF', color: '#fff', fontWeight: 750, padding: '14px 26px', borderRadius: 980, textDecoration: 'none' }}>
              Generate a free Short
            </OrganicCtaLink>
          )}
          <OrganicCtaLink href={signupUrl} source={CAMPAIGN} placement="hero_signup" style={{ border: '1px solid #D2D2CD', color: '#0E1116', fontWeight: 750, padding: '14px 22px', borderRadius: 980, textDecoration: 'none' }}>
            Start from scratch
          </OrganicCtaLink>
        </div>
        <p style={{ fontSize: 13, color: '#0A5CFF', fontWeight: 750, margin: '12px 0 0' }}>
          {ft(OFFER, 'Up to 3 watermarked Fast videos every 24h. No card required.', OFFER.copy.headline)}
        </p>

        {/* KINEO-POUSO-AFILIADO-CELULAR-1311 — para o afiliado o formulário já está no topo; aqui só para os outros. */}
        {!partnerContext && topicForm}

        {/* KINEO-PAGINAS-IA-CLARAS-2110 — o exemplo e os 3 vídeos velhos saíram; a âncora #example fica na vitrine atual (a mesma da /claude-connector). */}
        <PaginaClaraVitrine id="example" eyebrow="Real Kineo output" nota="These previews demonstrate the output format, not views or revenue performance." align="left" />
        <p style={{ ...p, marginTop: 10, fontSize: 13, textAlign: 'center' }}>
          <a href="/made-with-kineo" style={{ color: '#0A5CFF', textDecoration: 'none', fontWeight: 700 }}>See all real examples →</a>
        </p>
        {/* AQUISICAO T9 (14/08) — exit-intent na porta que mais recebe SEO:
            quem vai embora sem agir leva a oferta de CADASTRO (variant free),
            nao tabela de preco. Mesmo componente da home. */}
        <ExitIntentOffer variant="free" />

        <h2 style={h2}>What the free test includes</h2>
        <div style={{ display: 'grid', gap: 12 }}>
          {FEATURES.map((feature) => (
            <div key={feature.t} style={card}>
              <h3 style={{ margin: 0, fontSize: '1.04rem' }}>{feature.t}</h3>
              <p style={{ ...p, fontSize: 14, margin: '7px 0 0' }}>{feature.d}</p>
            </div>
          ))}
        </div>

        <h2 style={h2}>Made for posting, not just drafting</h2>
        <p style={p}>
          A script generator gives you text. A clipper needs footage you already recorded. Kineo creates the whole Short from an idea, so the free test shows the actual workflow: prompt, voice, visuals, captions, and export.
        </p>
        <p style={p}>
          Want a more specific path? See the <Link href="/faceless-video-generator" style={{ color: '#0A5CFF' }}>faceless video generator</Link>, <Link href="/text-to-video-shorts" style={{ color: '#0A5CFF' }}>text to video Shorts</Link>, <Link href="/youtube-shorts-from-topic" style={{ color: '#0A5CFF' }}>YouTube Shorts from a topic</Link>, or <Link href="/free-ai-shorts" style={{ color: '#0A5CFF' }}>free AI Shorts by niche</Link>.
        </p>

        <h2 style={h2}>Frequently asked questions</h2>
        <div style={{ display: 'grid', gap: 10 }}>
          {FAQ.map((item) => (
            <div key={item.q} style={card}>
              <div style={{ fontWeight: 750, color: '#0E1116' }}>{item.q}</div>
              <p style={{ ...p, fontSize: 14, margin: '6px 0 0' }}>{item.a}</p>
            </div>
          ))}
        </div>

        <div style={{ marginTop: 44, textAlign: 'center', background: 'radial-gradient(circle at 50% 0%, #E8EFFF, #FFFFFF 70%)', border: '1px solid rgba(10,92,255,0.35)', borderRadius: 18, padding: '34px 22px' }}>
          <div style={{ fontSize: 'clamp(1.3rem, 4vw, 1.85rem)', fontWeight: 750 }}>Generate the first Short now.</div>
          <p style={{ color: '#5A5F67', margin: '8px 0 18px' }}>{OFFER.copy.headline}</p>
          <OrganicCtaLink href={`#${FORM_ID}`} source={CAMPAIGN} placement="final" style={{ background: '#0A5CFF', color: '#fff', fontWeight: 750, padding: '14px 30px', borderRadius: 980, textDecoration: 'none' }}>
            Try the free generator
          </OrganicCtaLink>
        </div>
        {/* KINEO-PAGINAS-LOTE1-2026-10-12 — irmãs do lote 1: quem chega aqui pergunta pela marca d'água e pelo filme longo. */}
        <p style={{ marginTop: 28, textAlign: 'center', fontSize: 14, color: '#5A5F67' }}>
          Related:{' '}
          <Link href="/ai-shorts-generator-no-watermark" style={{ color: '#0A5CFF', textDecoration: 'none', fontWeight: 700 }}>AI Shorts with no watermark — what is free and what is paid</Link>
          {' · '}
          <Link href="/ai-short-film-generator" style={{ color: '#0A5CFF', textDecoration: 'none', fontWeight: 700 }}>AI short film generator</Link>
        </p>
      </div>
      <Footer />
    </main>
  )
}

import CitationIdeaForm from '@/components/seo/CitationIdeaForm'
// SEO — /how-much-do-youtube-shorts-pay: money-intent page targeting
// "how much do youtube shorts pay" and long-tails ("per 1000 views",
// "for 1 million views", "shorts CPM/RPM"). Server component — o "zero client
// JS" que este cabeçalho dizia caiu em 14/08 (CalculatorClient) e em 15/08
// (TopicGeneratorForm): DUAS ilhas de cliente, resto server e `force-static`.
// dark theme matching /state-of-ai-shorts-2026 and /facts. Every payout figure
// is labelled as an ESTIMATED TYPICAL RANGE, never a guarantee — Shorts payouts
// vary widely by niche and geography. FAQPage + BreadcrumbList + Article JSON-LD
// mirror the visible page so the markup can never drift from what a human reads.

import type { Metadata } from 'next'
import GoogleCreatorDoor from '@/components/seo/GoogleCreatorDoor'
import { getFreeTierOffer, swapFreeTierCopy as ft } from '@/lib/freeTierOffer'
import OrganicCtaLink from '@/components/OrganicCtaLink'
// KINEO-STARTER-EM-ARTIGO-2026-08-15 — o MESMO componente da home/#70, nunca
// uma cópia. Ver o bloco de comentário no corpo. Client island; o resto da
// página segue server e `force-static` continua valendo.
import TopicGeneratorForm from '@/app/youtube-shorts-from-topic/TopicGeneratorForm'
// KINEO-FERRAMENTA-NA-PAGINA-2026-08-14 — ver o bloco de comentário no corpo.
// A calculadora não é duplicada: é O MESMO componente que /shorts-money-calculator
// renderiza, importado. Uma cópia teria duas RPMs para manter e elas divergiriam.
import CalculatorClient from '@/app/shorts-money-calculator/CalculatorClient'

// ── KINEO-SEO-SEM-PORTA-2026-08-14 ──────────────────────────────────────────
// MEDIDO no banco (30 dias, eventos por página de entrada): esta página teve
// 27 sessões e emitiu UM ÚNICO tipo de evento — `landing_session_started`.
// Nada mais. A causa não era falta de instrumentação: era falta de SAÍDA.
// O grep por `href="/signup"`, `href="/generate"` e por qualquer CTA nas 442
// linhas do arquivo voltou VAZIO.
//
// A seção "Keep going" no fim linkava para outras QUATRO páginas de SEO, que
// por sua vez linkam entre si. O interlinking existia e funcionava — só que
// como um circuito FECHADO: o visitante circula pelo labirinto de conteúdo e
// nunca encontra o produto. É a lição de 13/08 ("110 baixaram, 41 nunca viram
// um preço") aplicada um degrau antes: aqui a pergunta não foi feita nem uma
// vez. Uma taxa de conversão de 0% e uma oferta que nunca aparece produzem o
// mesmo número e pedem consertos opostos.
//
// Somadas, esta página e /state-of-ai-shorts-2026 receberam 55 sessões em 30
// dias sem nenhuma porta para o produto. O padrão que CONVERTE já existe na
// casa: /free-script-generator fez 6 cliques de CTA em 9 sessões usando
// exatamente o componente abaixo. Não falta página nova — falta a porta nas
// que já têm tráfego.
//
// KINEO-STARTER-EM-ARTIGO-2026-08-15 — `CTA_CAMPAIGN`/`CTA_HREF`
// (`seo_shorts_pay` → `/signup?next=/generate&utm_source=seo&utm_campaign=shorts_pay`)
// saíram daqui junto com a porta que os usava. O starter carrega a mesma
// intenção com create_intent=fast e o tema do leitor junto; deixar as duas
// constantes órfãs no topo seria a próxima leitura errada de quem chegar aqui.
//
// UM nome para o `source` e UM para o id da âncora, porque os dois aparecem em
// lugares diferentes do arquivo e duas cópias divergem (foi assim que o estudo
// vivo envelheceu: número chumbado em dois lugares).
const STARTER_SOURCE = 'starter_shorts_pay'
const PAYOUT_STARTER_ID = 'payout-start-a-short'

// [KINEO-TRIAL-SWAP-2026-08-07] — oferta do free tier (flag OFF = copy atual).
const OFFER = getFreeTierOffer()

export const dynamic = 'force-static'

const UPDATED = 'August 29, 2026'
const DATE_PUBLISHED = '2026-07-24'
const DATE_MODIFIED = '2026-08-29'
const CANONICAL_URL = 'https://www.usekineo.com/how-much-do-youtube-shorts-pay'
const YOUTUBE_SHORTS_POLICY_URL = 'https://support.google.com/youtube/answer/12504220?hl=en'
const YOUTUBE_YPP_URL = 'https://support.google.com/youtube/answer/72851?hl=en'
const YOUTUBE_YPP_2027_URL = 'https://support.google.com/youtube/answer/12843009?hl=en'

export const metadata: Metadata = {
  title: 'How Much Do YouTube Shorts Pay in 2026? (Per 1K & 1M Views)',
  description:
    'How much do YouTube Shorts pay? Estimated payouts per 1K and 1M views, the official 45% revenue share, current YPP rules, and the February 2027 changes.',
  alternates: { canonical: CANONICAL_URL },
  openGraph: {
    title: 'How Much Do YouTube Shorts Pay in 2026? (Per 1K & 1M Views)',
    description:
      'Estimated Shorts payouts per 1K and 1M views, what YouTube officially confirms, current YPP requirements, and the February 2027 changes.',
    url: CANONICAL_URL,
    type: 'article',
  },
  twitter: {
    card: 'summary_large_image',
    title: 'How Much Do YouTube Shorts Pay in 2026?',
    description:
      'Estimated Shorts payouts per 1K and 1M views, the official 45% revenue share, current YPP rules, and the February 2027 changes.',
  },
}

// Estimated typical Shorts RPM band (USD per 1,000 Shorts views), after
// YouTube's revenue split. NOT a guarantee — real RPM swings hard by niche
// and audience geography. Low/mid/high are illustrative ends of a common band.
const RPM_LOW = 0.03
const RPM_MID = 0.05
const RPM_HIGH = 0.1

