function money(views: number, rpm: number): string {
  const usd = (views / 1000) * rpm
  if (usd < 1) return `$${usd.toFixed(2)}`
  if (usd < 1000) return `$${usd.toFixed(0)}`
  return `$${usd.toLocaleString('en-US', { maximumFractionDigits: 0 })}`
}

